                    Report("DuplicateSection", SemanticSeverity.Error, property.Name, null, null, "The section appears more than once; the repeat is retained verbatim.");
                }
                else if (isExpected == false)
                {
                    Report("SectionUnexpected", SemanticSeverity.Warning, property.Name, null, null, "The contract does not declare this section; it is retained verbatim.");
                }

                builder.Add(new SemanticDocumentSection(property.Name, ordinal, property.Value, isExpected, duplicate));
