            var presentExpected = builder.Where(section => section.Expected).Select(section => section.Name).ToList();
            var declaredOrder = expectedSections.Where(name => seen.Contains(name)).ToList();
            if (presentExpected.SequenceEqual(declaredOrder, StringComparer.Ordinal) == false)
