        /// <summary>
        /// Classifies one row of a typed section: an entity, a declared marker, or unprojected.
        /// Checks that the row is an object without duplicate properties and that its label,
        /// scope and discriminator agree with the contract and the requested identity.
        /// </summary>
        public SemanticRowDisposition Classify(string section, JsonElement row, int index, out string? marker)
